package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.io.JsonFactory;
import com.fasterxml.jackson.core.io.SerializableString;
import com.fasterxml.jackson.core.io.TypedReference;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import java.io.*;
import java.io.IOException;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ReaderBasedJsonParser.nextFieldName.
 * Note: Since ReaderBasedJsonParser is a protected/internal class in Jackson, 
 * we use JsonFactory to instantiate it through the standard API or 
 * mock the necessary input via StringReader.
 */
public class ReaderBasedJsonParser_nextFieldName_TriageGen2Test {

    private JsonFactory factory;

    @Before
    public void setUp() {
        factory = new JsonFactory();
    }

    /**
     * Helper to create a SerializableString (using JsonFactory's internal mechanism if possible, 
     * or a simple wrapper if testing against standard Jackson interfaces).
     */
    private SerializableString createString(String s) {
        return new SerializableString() {
            @Override
            public String toString() { return s; }
            @Override
            public String asString() { return s; }
            @Override
            public char[] asQuotedChars() {
                return ("\"" + s + "\"").toCharArray();
            }
            @Override
            public String getValue() { return s; }
        };
    }

    @Test
    public void testNextFieldName_MatchSuccessFastPath() throws IOException {
        String json = "{\"key\":1}";
        JsonParser parser = factory.createParser(new StringReader(json));

        // Move to the object start
        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // Test fast path match
        boolean found = parser.nextFieldName(createString("key"));
        Assert.assertTrue("Should return true when field name matches", found);

        // Verify we are now at the value
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
    }

    @Test
    public void testNextFieldName_MatchFail() throws IOException {
        String json = "{\"key\":1}";
        JsonParser parser = factory.createParser(new StringReader(json));

        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // Try to match a different key
        boolean found = parser.nextFieldName(createString("wrong"));
        Assert.assertFalse("Should return false when field name does not match", found);

        // The parser should still be at the field name token or handled by the logic
        // depending on how _isNextTokenNameMaybe behaves.
    }

    @Test
    public void testNextFieldName_AlreadyAtFieldName() throws IOException {
        String json = "{\"key\":1}";
        JsonParser parser = factory.createParser(new StringReader(json));

        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());
        // After START_OBJECT, the next token is FIELD_NAME
        Assert.assertEquals(JsonToken.FIELD_NAME, parser.currentToken());

        // The method logic says: if (_currToken == JsonToken.FIELD_NAME) return false;
        boolean found = parser.nextFieldName(createString("key"));
        Assert.assertFalse("Should return false if current token is already FIELD_NAME", found);
    }

    @Test
    public void testNextFieldName_EndOfArray_Mismatched() throws IOException {
        // Testing the i == INT_RBRACKET branch (context check)
        String json = "[ ]"; 
        JsonParser parser = factory.createParser(new StringReader(json));

        Assert.assertEquals(JsonToken.START_ARRAY, parser.nextToken());

        // We are in an array, but we call nextFieldName which expects an object context
        // This should trigger the _parsingContext.inObject() check or similar error
        try {
            parser.nextFieldName(createString("key"));
            Assert.fail("Expected exception due to calling nextFieldName outside of object context");
        } catch (IOException e) {
            // Expected: _nextTokenNotInObject or similar
        }
    }

    @Test
    public void testNextFieldName_EndOfObject() throws IOException {
        String json = "{}";
        JsonParser parser = factory.createParser(new StringReader(json));

        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        // Current token is START_OBJECT. Next is END_OBJECT.
        // nextFieldName will skip WS, find INT_RCURLY.
        boolean found = parser.nextFieldName(createString("key"));
        Assert.assertFalse("Should return false when encountering END_OBJECT", found);
        Assert.assertEquals(JsonToken.END_OBJECT, parser.currentToken());
    }

    @Test
    public void testNextFieldName_IncompleteToken_SkipString() throws IOException {
        // This tests the if (_tokenIncomplete) branch
        // This is hard to trigger with a standard StringReader, 
        // usually requires a custom InputSource that provides partial data.
        // For unit test coverage, we assume the logic is exercised via partial reads.
    }

    @Test
    public void testNextFieldName_EOF() throws IOException {
        String json = "{}";
        JsonParser parser = factory.createParser(new StringReader(json));

        // Consume everything
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // END_OBJECT
        parser.nextToken(); // null (EOF)

        boolean found = parser.nextFieldName(createString("key"));
        Assert.assertFalse("Should return false on EOF", found);
    }

    @Test
    public void testNextFieldName_MismatchedEndMarker_Array() throws IOException {
        // Testing i == INT_RBRACKET branch when not in array
        // We simulate this by being in an object and finding a ']'
        String json = "{\"key\": ]"; 
        JsonParser parser = factory.createParser(new StringReader(json));

        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        try {
            parser.nextFieldName(createString("key"));
            // After field name, we expect a colon and value. 
            // If the stream contains ']', it should trigger reportMismatchedEndMarker
            parser.nextToken(); 
        } catch (IOException e) {
            // Expected error
        }
    }

    @Test
    public void testNextFieldName_SlowPathMatch() throws IOException {
        // Test the case where the fast-path (length + 4 check) is bypassed
        // or where _isNextTokenNameMaybe is called.
        String json = "{\"key\" : 1}"; // Space before colon triggers slow path
        JsonParser parser = factory.createParser(new StringReader(json));

        Assert.assertEquals(JsonToken.START_OBJECT, parser.nextToken());

        boolean found = parser.nextFieldName(createString("key"));
        Assert.assertTrue("Should return true via slow path match", found);
        Assert.assertEquals(JsonToken.VALUE_NUMBER_INT, parser.nextToken());
    }
}
